const state={page:'overview',project:'P-024',tab:'summary',query:'',projectFilter:'all',status:'all',view:'gantt',week:'2026-11-02',resource:'crews',from:'',to:'',menu:false};
const P=id=>db.projects.find(p=>p.id===id);const T=id=>db.tasks.find(t=>t.id===id);const sum=a=>a.reduce((s,n)=>s+n,0);
const projectTasks=id=>db.tasks.filter(t=>t.project===id);
const approved=id=>db.logs.filter(l=>l.project===id&&l.status==='Patvirtinta');
const actual=id=>CAT.map((_,i)=>sum(approved(id).map(l=>l.costs[i])));
const committed=p=>CAT.map((_,i)=>Number(p.committed?.[i])||0);
const metrics=p=>{const a=actual(p.id),cost=sum(a),budget=sum(p.budget),forecast=cost+sum(p.remaining);return {actual:a,committed:committed(p),commitment:sum(committed(p)),otherRemaining:CAT.map((_,i)=>Math.max(0,p.remaining[i]-committed(p)[i])),cost,budget,forecast,margin:p.revenue?(p.revenue-forecast)/p.revenue*100:0,variance:budget-forecast,progress:progress(p.id)}};
const taskQty=id=>sum(db.logs.filter(l=>l.task===id&&l.status==='Patvirtinta').map(l=>l.qty));
const taskProgress=t=>Math.min(100,t.qty?taskQty(t.id)/t.qty*100:0);
function progress(id){const ts=projectTasks(id),w=sum(ts.map(t=>t.weight));return w?Math.round(sum(ts.map(t=>taskProgress(t)*t.weight))/w):0}
const taskStatus=t=>taskProgress(t)>=100?'Atlikta':t.end<today()?'Vėluoja':taskQty(t.id)>0?'Vykdoma':'Planuojama';
const options=(arr,value,all='')=>(all?`<option value="all">${E(all)}</option>`:'')+arr.map(x=>`<option value="${E(x.id??x)}" ${String(x.id??x)===String(value)?'selected':''}>${E(x.name??x)}</option>`).join('');
const tag=s=>{let tone=['Patvirtinta','Atlikta','Užbaigtas','Aktuali'].includes(s)?'green':['Laukia tvirtinimo','Vėluoja','Viršijimas','Reikia dėmesio'].includes(s)?(s==='Vėluoja'||s==='Viršijimas'?'red':'amber'):['Vykdomas','Vykdoma'].includes(s)?'blue':'gray';return `<span class="tag ${tone}"><i class="dot"></i>${E(s)}</span>`};
const btn=(text,action,extra='',cls='')=>`<button class="${cls}" data-action="${action}" ${extra}>${text}</button>`;
const iconBtn=(name,label,action,extra='',cls='')=>btn(icon(name)+E(label),action,extra,'btn-icon '+cls);
function notify(s){document.getElementById('notification').innerHTML=`<div class="toast" role="status">${icon('check')}${E(s)}</div>`;clearTimeout(notify.timer);notify.timer=setTimeout(()=>document.getElementById('notification').innerHTML='',3600)}
