function header(title,desc,actions='',over='OPERACIJŲ VALDYMAS'){return `<div class="page-head"><div><div class="eyebrow">${over}</div><h1>${E(title)}</h1><p>${E(desc)}</p></div><div class="page-actions">${actions}</div></div>`}
function kpi(label,value,note,ic='chart',pct){return `<article class="kpi"><div class="label">${E(label)}${icon(ic)}</div><div class="value">${value}</div><p>${note}</p>${pct!==undefined?`<div class="mini"><i style="width:${Math.min(100,pct)}%"></i></div>`:''}</article>`}
function progressEl(v){return `<div class="progress-label"><div class="progress"><i style="width:${Math.min(100,v)}%"></i></div><span>${num(v)}%</span></div>`}
function empty(text){return `<div class="empty">${icon('folder')}${E(text)}</div>`}
function projectFilter(){return `<select id="project-filter" aria-label="Objekto filtras">${options(db.projects,state.projectFilter,'Visi objektai')}</select>`}
function searchMatch(text){return String(text).toLocaleLowerCase('lt').includes(state.query.toLocaleLowerCase('lt'))}
function projectTable(ps,compact=false){return ps.length?`<div class="table-wrap"><table><thead><tr><th>Objektas / užsakovas</th>${compact?'':'<th>Atsakingas</th>'}<th>Darbų eiga</th><th class="num">Sąmata</th><th class="num">Faktas</th><th class="num">Prognozės nuokrypis</th><th>Būsena</th></tr></thead><tbody>${ps.map(p=>{let m=metrics(p);return `<tr class="clickable" data-action="open-project" data-id="${p.id}"><td><button class="rowlink" data-action="open-project" data-id="${p.id}">${E(p.name)}</button><small>${E(p.client)} · ${E(p.id)}</small></td>${compact?'':`<td>${E(p.manager)}<small>Iki ${full(p.end)}</small></td>`}<td style="min-width:130px">${progressEl(m.progress)}</td><td class="num">${money(m.budget)}</td><td class="num">${money(m.cost)}</td><td class="num ${m.variance<0?'negative':'positive'}">${m.variance>=0?'+':''}${money(m.variance)}</td><td>${tag(p.state)}</td></tr>`}).join('')}</tbody></table></div>`:empty('Pagal pasirinktus filtrus objektų nėra.')}
function overview(){const ps=db.projects.filter(p=>p.state!=='Užbaigtas'),ms=ps.map(metrics),budget=sum(ms.map(m=>m.budget)),cost=sum(ms.map(m=>m.cost)),forecast=sum(ms.map(m=>m.forecast)),pending=db.logs.filter(l=>l.status==='Laukia tvirtinimo'),pendingRevenue=db.incomes.filter(r=>r.status==='Laukia tvirtinimo');const due=db.tasks.filter(t=>taskStatus(t)==='Vėluoja');let risk=ps.filter(p=>metrics(p).variance<0);return header('Projektų apžvalga','Patvirtintų projektų pajamos, sąnaudos ir darbų eiga.',iconBtn('plus','Naujas projektas','new-project','','primary'),`PENKTADIENIS · ${full(today())}`)+`<div class="kpis">${kpi('Aktyvių objektų sąmata',money(budget),`${ps.length} vykdomi ir planuojami objektai`,'euro')}${kpi('Patvirtintos sąnaudos',money(cost),`${num(budget?cost/budget*100:0,1)}% patvirtintos sąmatos`,'cost',budget?cost/budget*100:0)}${kpi('Patvirtintos pajamos',money(sum(ps.map(p=>actualIncome(p.id)))),`<span class="${sum(ps.map(p=>actualIncome(p.id)))-cost<0?'negative':'positive'}">${money(sum(ps.map(p=>actualIncome(p.id)))-cost)} einamasis rezultatas</span>`,'euro')}${kpi('Laukia tvirtinimo',String(pending.length+pendingRevenue.length),`${pending.length} dienos · ${pendingRevenue.length} pajamų įrašai`,'journal')}</div><div class="two-col"><section class="card"><div class="card-head"><div><div class="eyebrow">FINANSINĖ PADĖTIS</div><h2>Sąmata ir patvirtintas faktas</h2></div>${btn('Visos sąnaudos →','nav','data-page="budget"','subtle')}</div><div class="chart">${db.projects.map(p=>{let m=metrics(p),max=Math.max(...db.projects.map(x=>metrics(x).budget));return `<div class="chart-col" title="${E(p.name)}: sąmata ${money(m.budget)}, faktas ${money(m.cost)}"><div class="chart-bars"><i style="height:${m.budget/max*110}px"></i><i class="fact" style="height:${m.cost/max*110}px"></i></div><span>${E(p.id)}</span></div>`}).join('')}</div><div class="legend"><span><i></i>Sąmata</span><span><i class="fact"></i>Patvirtintas faktas</span></div>${portfolioReserve()}</section><section class="card"><div class="card-head"><div><div class="eyebrow">REIKIA VEIKSMO</div><h2>Darbo eilė</h2></div><span class="number-pill">${pending.length+pendingRevenue.length+risk.length+due.length+db.docs.filter(d=>d.status==='Laukia tvirtinimo').length}</span></div>${pending.slice(0,2).map(l=>`<div class="alert-row"><div class="alert-icon">${icon('journal')}</div><div><b>${E(l.id)} · patvirtinti dienos faktą</b><p>${E(P(l.project).name)}<br>${num(l.qty)} ${E(T(l.task)?.unit)} · ${money(sum(l.costs))}</p></div>${btn(icon('right'),'log-detail',`data-id="${l.id}" aria-label="Atverti įrašą ${l.id}"`)}</div>`).join('')}${pendingRevenue.slice(0,1).map(r=>`<div class="alert-row"><div class="alert-icon">${icon('euro')}</div><div><b>${E(r.id)} · patvirtinti pajamas</b><p>${E(P(r.project).name)}<br>${E(r.ref)} · ${money(r.amount)}</p></div>${btn(icon('right'),'income-detail',`data-id="${r.id}" aria-label="Atverti pajamas ${r.id}"`)}</div>`).join('')}${risk.map(p=>`<div class="alert-row"><div class="alert-icon red">${icon('alert')}</div><div><b>Sąmatos viršijimo prognozė</b><p>${E(p.name)}<br>${money(-metrics(p).variance)} virš sąmatos</p></div>${btn(icon('right'),'project-budget',`data-id="${p.id}" aria-label="Atverti sąmatą"`)}</div>`).join('')}${db.docs.filter(d=>d.status==='Laukia tvirtinimo').slice(0,1).map(d=>`<div class="alert-row"><div class="alert-icon">${icon('file')}</div><div><b>${E(d.name)}</b><p>${E(P(d.project).name)}<br>Laukia atsakingo asmens patvirtinimo</p></div>${btn(icon('right'),'doc-detail',`data-id="${d.id}" aria-label="Peržiūrėti dokumentą"`)}</div>`).join('')}${due.slice(0,1).map(t=>`<div class="alert-row"><div class="alert-icon red">${icon('clock')}</div><div><b>Vėluoja: ${E(t.name)}</b><p>${E(P(t.project).name)} · terminas ${full(t.end)}</p></div>${btn(icon('right'),'edit-task',`data-id="${t.id}" aria-label="Peržiūrėti etapą"`)}</div>`).join('')}${!pending.length&&!pendingRevenue.length&&!risk.length&&!due.length&&!db.docs.some(d=>d.status==='Laukia tvirtinimo')?empty('Neatliktų veiksmų nėra.'):''}</section></div><section class="card"><div class="card-head"><div><div class="eyebrow">PROJEKTŲ PORTFELIS</div><h2>Aktyvūs objektai</h2></div>${btn('Visi projektai →','nav','data-page="projects"','subtle')}</div>${projectTable(ps,true)}<div class="card-foot"><span>Faktas iš patvirtintų dienos žurnalo įrašų</span><span>${ps.length} objektai</span></div></section>`}
function projectsPage(){let ps=db.projects.filter(p=>(state.status==='all'||p.state===state.status)&&searchMatch(p.name+' '+p.client+' '+p.id+' '+p.manager));return header('Projektai','Sutartys, terminai, atsakingi asmenys ir projekto rezultatas.',iconBtn('plus','Naujas projektas','new-project','','primary'))+`<section class="card"><div class="filterbar"><select id="status-filter" aria-label="Projekto būsena">${options(['Vykdomas','Planuojamas','Užbaigtas'],state.status,'Visos būsenos')}</select><span class="grow">${ps.length} iš ${db.projects.length} objektų</span>${iconBtn('down','Eksportuoti','export-projects')}</div>${projectTable(ps)}</section>`}
function selectedProject(){let p=P(state.project)||db.projects[0],m=metrics(p),ts=projectTasks(p.id),ls=db.logs.filter(l=>l.project===p.id),docs=db.docs.filter(d=>d.project===p.id);return header('Projekto valdymas','Objekto planas, dienos faktas ir finansai.',`<select class="header-select" id="selected-project" aria-label="Pasirinkti projektą">${options(db.projects,p.id)}</select>${iconBtn('edit','Projekto duomenys','edit-project',`data-id="${p.id}"`)}`,'PROJEKTAI / '+p.id)+`<section class="card"><div class="project-banner"><div class="project-icon">${icon('road')}</div><div class="project-info"><div class="line"><h2>${E(p.name)}</h2>${tag(p.state)}</div><p>${E(p.client)} · Sutartis ${E(p.contract)} · ${E(p.manager)}</p></div>${iconBtn('plus','Dienos įrašas','new-log',`data-project="${p.id}"`,'primary')}</div><div class="tabs">${[['summary','Suvestinė',''],['plan','Etapai ir Gantt',ts.length],['budget','Sąmata ir faktas',''],['costdetail','Sąnaudų detalės',''],['income','Pajamos',db.incomes.filter(r=>r.project===p.id).length],['journal','Dienos žurnalas',ls.length],['docs','Dokumentai',docs.length],['history','Istorija','']].map(([id,label,count])=>btn(E(label)+(count!==''?`<b>${count}</b>`:''),'tab',`data-tab="${id}"`,state.tab===id?'active':'')).join('')}</div>${state.tab==='summary'?projectSummary(p,m):state.tab==='plan'?`<div class="panel">${planToolbar(true)}</div>${gantt(ts)}${taskTable(ts)}`:state.tab==='budget'?budgetPanel(p):state.tab==='costdetail'?operationsDetail(p):state.tab==='income'?`<div class="panel"><div class="toolbar"><div><h3>Faktinės projekto pajamos</h3><p>Sutarties vertė ${money(p.revenue)} · Patvirtintos pajamos ${money(actualIncome(p.id))}</p></div>${iconBtn('plus','Registruoti pajamas','new-income',`data-project="${p.id}"`,'primary')}</div></div>${incomeTable(db.incomes.filter(r=>r.project===p.id))}`:state.tab==='journal'?`<div class="panel"><div class="toolbar"><div><h3>Objekto dienos įrašai</h3><p>Patvirtinti įrašai įtraukiami į sąnaudas ir atliktų darbų kiekius.</p></div>${iconBtn('plus','Naujas įrašas','new-log',`data-project="${p.id}"`)}</div></div>${logTable(ls)}`:state.tab==='docs'?`<div class="panel"><div class="toolbar"><h3>Projekto dokumentų registras</h3>${iconBtn('upload','Įkelti dokumentą','new-doc',`data-project="${p.id}"`)}</div></div>${docTable(docs)}`:`<div class="panel">${activity(p.id)}</div>`}</section>`}
function projectSummary(p,m){let ts=projectTasks(p.id),pending=db.logs.filter(l=>l.project===p.id&&l.status==='Laukia tvirtinimo');return `<div class="panel"><div class="project-stats"><div><small>Sąmata</small><strong>${money(m.budget)}</strong><p>Sutarties vertė ${money(p.revenue)}</p></div><div><small>Patvirtintas faktas</small><strong>${money(m.cost)}</strong><p>${approved(p.id).length} patvirtinti įrašai</p></div><div><small>Prognozė užbaigus</small><strong>${money(m.forecast)}</strong><p class="${m.variance<0?'negative':''}">${m.variance<0?'Virš sąmatos':'Sąmatos rezervas'} ${money(Math.abs(m.variance))}</p></div><div><small>Darbų eiga</small><strong>${m.progress}%</strong><p>Terminas ${full(p.end)}</p></div></div><div class="project-stats"><div><small>Patvirtintos pajamos</small><strong>${money(actualIncome(p.id))}</strong><p>Pagal patvirtintus pajamų įrašus</p></div><div><small>Einamasis rezultatas</small><strong class="${actualIncome(p.id)-m.cost<0?'negative':'positive'}">${money(actualIncome(p.id)-m.cost)}</strong><p>Patvirtintos pajamos minus sąnaudos</p></div><div><small>Darbuotojų valandos / DU</small><strong>${num(sum(approved(p.id).map(l=>l.hours)),1)} val.</strong><p>${money(m.actual[0])} DU sąnaudų</p></div><div><small>Technikos motovalandos</small><strong>${num(sum(approved(p.id).map(l=>l.machineHours||0)),1)} motov.</strong><p>${money(m.actual[2])} technikai ir kurui</p></div></div><div class="summary-grid"><div><div class="section-title">Etapų vykdymas <span>Pagal patvirtintus kiekius</span></div>${ts.length?ts.map((t,i)=>`<div class="stage"><span class="stage-index ${taskProgress(t)>=100?'done':''}">${taskProgress(t)>=100?'✓':i+1}</span><div><b>${E(t.name)}</b><small>${short(t.start)}–${short(t.end)} · ${num(taskQty(t.id))} / ${num(t.qty)} ${E(t.unit)}</small></div>${progressEl(taskProgress(t))}</div>`).join(''):empty('Pridėkite pirmą projekto etapą.')}<div style="margin-top:14px">${btn('Atidaryti darbų planą →','tab','data-tab="plan"','subtle')}</div></div><div><div class="section-title">Sąnaudų struktūra <span>Faktas / sąmata</span></div>${CAT.map((c,i)=>`<div class="costbar"><div class="costbar-line"><b>${E(c)}</b><span>${money(m.actual[i])} / ${money(p.budget[i])}</span></div><div class="progress"><i style="width:${Math.min(100,p.budget[i]?m.actual[i]/p.budget[i]*100:0)}%"></i></div></div>`).join('')}<div class="reserve-strip compact"><div><span class="reserve-swatch"></span><b>Rezervas</b><p>Pagal projekto užbaigimo prognozę</p></div><strong class="${m.variance<0?'negative':'positive'}">${money(Math.max(0,m.variance))}</strong></div><p class="hint">Įsipareigota ${money(m.commitment)} · įskaičiuota į likusių darbų sąnaudas.</p><div class="note-box">${icon('chart')}<div>Prognozuojama marža <b>${num(m.margin,1)}%</b><br>Sutarties vertė atėmus faktą ir likusių darbų sąnaudas.</div></div>${btn('Atidaryti sąmatą →','tab','data-tab="budget"','subtle')}</div></div>${pending.length?`<div class="note-box amber">${icon('clock')}<div><b>${pending.length} dienos įrašas laukia tvirtinimo.</b> ${money(sum(pending.map(l=>sum(l.costs))))} dar neįtraukta į faktą. ${btn('Peržiūrėti →','tab','data-tab="journal"','subtle')}</div></div>`:''}<div class="subhead"><h3>Paskutiniai pakeitimai</h3>${btn('Visa istorija →','tab','data-tab="history"','subtle')}</div>${activity(p.id,3)}</div>`}
function activity(id,limit=50){let a=db.activity.filter(a=>!id||a.project===id).slice(0,limit);return a.length?a.map(a=>`<div class="activity"><div class="activity-time">${short(a.date.slice(0,10))}<br>${a.date.slice(11,16)}</div><div><b>${E(a.text)}</b><p>${E(a.detail)}</p></div></div>`).join(''):empty('Projekto pakeitimų dar nėra.')}
function planToolbar(projectOnly=false){return `<div class="toolbar"><div><h3>${projectOnly?'Projekto darbų planas':'Darbų paskirstymas'}</h3><p>Brigadų ir technikos rezervavimas pagal etapų datas.</p></div><div class="page-actions"><div class="week-switch">${btn(icon('left'),'week-prev','aria-label="Ankstesnės dvi savaitės"')}<span>${short(state.week)} – ${short(plusDate(state.week,13))}</span>${btn(icon('right'),'week-next','aria-label="Kitos dvi savaitės"')}</div>${iconBtn('plus','Pridėti etapą','new-task',projectOnly?`data-project="${state.project}"`:'','primary')}</div></div>`}
function schedulePage(){let ts=db.tasks.filter(t=>(state.projectFilter==='all'||t.project===state.projectFilter)&&(state.status==='all'||taskStatus(t)===state.status)&&searchMatch(t.name+' '+P(t.project).name+' '+t.crew));return header('Darbų planas','Etapai, terminai ir resursų paskirstymas.',iconBtn('down','Eksportuoti','export-plan'))+`<section class="card"><div class="panel">${planToolbar()}</div><div class="filterbar">${projectFilter()}<select id="status-filter" aria-label="Etapo būsena">${options(['Planuojama','Vykdoma','Atlikta','Vėluoja'],state.status,'Visos būsenos')}</select><div class="segmented">${btn('Gantt','plan-view','data-view="gantt"',state.view==='gantt'?'active':'')}${btn('Sąrašas','plan-view','data-view="list"',state.view==='list'?'active':'')}</div><span class="grow">${ts.length} etapai</span></div>${state.view==='gantt'?gantt(ts):taskTable(ts)}</section>`}
function gantt(ts){let dates=Array.from({length:14},(_,i)=>plusDate(state.week,i)),end=plusDate(state.week,13),visible=ts.filter(t=>t.end>=state.week&&t.start<=end);return `<div class="gantt"><div class="gantt-grid"><div>OBJEKTAS / ETAPAS</div>${dates.map(d=>`<div class="${day(d).getDay()%6===0?'weekend':''} ${d===today()?'today':''}">${['Sk','Pr','An','Tr','Kt','Pn','Št'][day(d).getDay()]}<br>${short(d)}</div>`).join('')}</div>${visible.length?visible.map(t=>{const offset=Math.max(0,Math.round((day(t.start)-day(state.week))/86400000)),last=Math.min(13,Math.round((day(t.end)-day(state.week))/86400000));return `<div class="gantt-row"><div class="gantt-name"><button class="rowlink" data-action="edit-task" data-id="${t.id}">${E(t.name)}</button><small>${E(P(t.project).id)} · Brigada ${E(t.crew)}${t.machine?' · '+E(t.machine):''}</small></div><div class="gantt-track"><button class="gantt-bar ${taskStatus(t)==='Vykdoma'?'running':''}" data-action="edit-task" data-id="${t.id}" style="grid-column:${offset+1}/span ${last-offset+1}" title="${E(t.name)} · ${full(t.start)}–${full(t.end)} · ${num(taskProgress(t))}%"><i style="width:${taskProgress(t)}%"></i><span>${num(taskProgress(t))}% · ${E(t.name)}</span></button></div></div>`}).join(''):empty('Šiuo laikotarpiu suplanuotų etapų nėra.')}</div><div class="card-foot"><span>Spustelėkite etapą, kad pakeistumėte datas ir resursus.</span><span>${visible.length} etapai laikotarpyje</span></div>`}
function taskTable(ts){return ts.length?`<div class="table-wrap"><table><thead><tr><th>Etapas / objektas</th><th>Laikotarpis</th><th>Brigada / technika</th><th class="num">Planuotas kiekis</th><th class="num">Atlikta</th><th>Būsena</th><th></th></tr></thead><tbody>${ts.map(t=>`<tr><td><button class="rowlink" data-action="edit-task" data-id="${t.id}">${E(t.name)}</button><small>${E(P(t.project).name)}</small></td><td>${short(t.start)} – ${short(t.end)}<small>2026 m.</small></td><td>Brigada ${E(t.crew)}<small>${E(machines.find(m=>m.id===t.machine)?.name||'Technika nepriskirta')}</small></td><td class="num">${num(t.qty)} ${E(t.unit)}</td><td class="num">${num(taskQty(t.id))} ${E(t.unit)}</td><td>${tag(taskStatus(t))}</td><td>${btn(icon('edit'),'edit-task',`data-id="${t.id}" aria-label="Redaguoti etapą ${E(t.name)}"`,'subtle')}</td></tr>`).join('')}</tbody></table></div>`:empty('Etapų pagal pasirinktus filtrus nėra.')}
function filteredLogs(){return db.logs.filter(l=>(state.projectFilter==='all'||l.project===state.projectFilter)&&(state.status==='all'||l.status===state.status)&&(!state.from||l.date>=state.from)&&(!state.to||l.date<=state.to)&&searchMatch(l.id+' '+P(l.project).name+' '+T(l.task)?.name+' '+l.author)).sort((a,b)=>b.date.localeCompare(a.date)||b.id.localeCompare(a.id))}
function journalPage(){let ls=filteredLogs();return header('Dienos žurnalas','Atlikti kiekiai, darbo laikas, medžiagos ir dienos sąnaudos.',iconBtn('plus','Naujas įrašas','new-log','','primary'))+`<div class="kpis">${kpi('Patvirtintų įrašų',String(db.logs.filter(l=>l.status==='Patvirtinta').length),'Įtraukti į projekto faktą','check')}${kpi('Laukia tvirtinimo',String(db.logs.filter(l=>l.status==='Laukia tvirtinimo').length),'Reikalinga projekto vadovo peržiūra','clock')}${kpi('Juodraščių',String(db.logs.filter(l=>l.status==='Juodraštis').length),'Galima papildyti ir pateikti tvirtinti','journal')}${kpi('Patvirtintos sąnaudos',money(sum(db.logs.filter(l=>l.status==='Patvirtinta').map(l=>sum(l.costs)))),'Visų objektų dienos įrašai','euro')}</div><section class="card"><div class="filterbar">${projectFilter()}<select id="status-filter" aria-label="Įrašo būsena">${options(['Juodraštis','Laukia tvirtinimo','Patvirtinta','Grąžinta tikslinti'],state.status,'Visos būsenos')}</select><input type="date" id="from-date" aria-label="Data nuo" value="${state.from}"><span class="muted">–</span><input type="date" id="to-date" aria-label="Data iki" value="${state.to}"><span class="grow">${ls.length} įrašai</span>${iconBtn('down','Eksportuoti','export-logs')}</div>${logTable(ls)}</section>`}
function logTable(ls){ls=[...ls].sort((a,b)=>b.date.localeCompare(a.date)||b.id.localeCompare(a.id));return ls.length?`<div class="table-wrap"><table><thead><tr><th>Data / įrašas</th><th>Objektas / etapas</th><th class="num">Kiekis</th><th class="num">Darbo laikas</th><th class="num">Sąnaudos</th><th>Būsena</th><th></th></tr></thead><tbody>${ls.map(l=>`<tr class="clickable" data-action="log-detail" data-id="${l.id}"><td><strong>${full(l.date)}</strong><small>${E(l.id)}</small></td><td><strong>${E(T(l.task)?.name||'Etapas')}</strong><small>${E(P(l.project).name)}</small></td><td class="num">${num(l.qty,2)} ${E(T(l.task)?.unit)}</td><td class="num">${num(l.hours,1)} val.</td><td class="num">${money(sum(l.costs))}<small>${E(l.author)}</small></td><td>${tag(l.status)}</td><td>${btn(icon('right'),'log-detail',`data-id="${l.id}" aria-label="Atidaryti įrašą ${l.id}"`,'subtle')}</td></tr>`).join('')}</tbody></table></div>`:empty('Įrašų pagal pasirinktus filtrus nėra.')}
function budgetPage(){const ps=state.projectFilter==='all'?db.projects:db.projects.filter(p=>p.id===state.projectFilter);const ms=ps.map(metrics),budget=sum(ms.map(m=>m.budget)),cost=sum(ms.map(m=>m.cost)),forecast=sum(ms.map(m=>m.forecast));return header('Sąmata ir faktas','Patvirtintos sąnaudos ir likusių darbų įvertinimas.',iconBtn('down','Eksportuoti','export-budget'))+`<div class="kpis">${kpi('Patvirtinta sąmata',money(budget),`${ps.length} objektai`,'euro')}${kpi('Faktinės sąnaudos',money(cost),'Tik patvirtinti dienos įrašai','check')}${kpi('Prognozė užbaigus',money(forecast),'Faktas + likusių darbų sąnaudos','chart')}${kpi('Sąmatos rezervas',`<span class="${budget-forecast<0?'negative':''}">${money(budget-forecast)}</span>`,budget-forecast<0?'Prognozuojamas sąmatos viršijimas':'Skirtumas tarp sąmatos ir prognozės','cost')}</div><section class="card"><div class="filterbar">${projectFilter()}<span class="grow">Sąmata ir prognozė: nuo projekto pradžios · be PVM</span></div>${state.projectFilter!=='all'?budgetPanel(P(state.projectFilter)):projectTable(ps)}</section><section class="card"><div class="card-head"><div><div class="eyebrow">EINAMOJI PROJEKTO KONTROLĖ</div><h2>Pajamos, DU, medžiagos ir technika</h2></div></div>${operationsDetail(state.projectFilter==='all'?null:P(state.projectFilter))}</section>`}
function budgetPanel(p){const m=metrics(p);return `<div class="panel"><div class="toolbar"><div><h3>Sąnaudos pagal kategoriją</h3><p>Prognozė = faktas + įsipareigota + kiti likę darbai.</p></div><div class="page-actions">${iconBtn('edit','Įsipareigojimai','edit-committed',`data-id="${p.id}"`)}${iconBtn('edit','Tikslinti likutį','edit-remaining',`data-id="${p.id}"`)}${btn('Užfiksuoti versiją','snapshot',`data-id="${p.id}"`)}</div></div></div><div class="table-wrap"><table><thead><tr><th>Kategorija</th><th class="num">Sąmata</th><th class="num">Faktas</th><th class="num">Įsipareigota</th><th class="num">Kiti likę darbai</th><th class="num">Prognozė</th><th class="num">Rezervas / viršijimas</th></tr></thead><tbody>${CAT.map((c,i)=>`<tr><td><button class="rowlink" data-action="cost-detail" data-project="${p.id}" data-cat="${i}">${E(c)}</button></td><td class="num">${money(p.budget[i])}</td><td class="num">${money(m.actual[i])}</td><td class="num">${money(m.committed[i])}</td><td class="num">${money(m.otherRemaining[i])}</td><td class="num">${money(m.actual[i]+m.committed[i]+m.otherRemaining[i])}</td><td class="num ${p.budget[i]-m.actual[i]-p.remaining[i]<0?'negative':'positive'}">${money(p.budget[i]-m.actual[i]-p.remaining[i])}</td></tr>`).join('')}<tr class="total"><td>Iš viso</td><td class="num">${money(m.budget)}</td><td class="num">${money(m.cost)}</td><td class="num">${money(m.commitment)}</td><td class="num">${money(sum(m.otherRemaining))}</td><td class="num">${money(m.forecast)}</td><td class="num ${m.variance<0?'negative':'positive'}">${money(m.variance)}</td></tr></tbody></table></div><div class="panel"><div class="reserve-strip"><div><span class="reserve-swatch"></span><b>Rezervas</b><p>Nepanaudota sąmatos dalis pagal dabartinę prognozę.</p></div><div><strong class="${m.variance<0?'negative':'positive'}">${money(Math.max(0,m.variance))}</strong>${m.variance<0?`<small class="negative">Prognozė viršija sąmatą ${money(-m.variance)}</small>`:`<small>${num(m.budget?m.variance/m.budget*100:0,1)}% patvirtintos sąmatos</small>`}</div></div><div class="note-box">${icon('chart')}<div>Sutarties vertė <b>${money(p.revenue)}</b> · Prognozuojamas rezultatas <b>${money(p.revenue-m.forecast)}</b> · Marža <b>${num(m.margin,1)}%</b><br>Įsipareigota – užsakyta, bet dar neįtraukta į faktą. Šios sumos jau įeina į likusių darbų įvertinimą ir papildomai prie jo nesumuojamos. Patvirtinus dienos faktą, mažinamos atitinkamos kategorijos likusių darbų ir įsipareigojimų sumos.</div></div><div class="subhead"><h3>Užfiksuotos sąmatos versijos</h3><span class="muted" style="font-size:10px">${db.versions.filter(v=>v.project===p.id).length} versijos</span></div>${db.versions.filter(v=>v.project===p.id).map(v=>`<div class="version"><div><b>V${v.number} · ${full(v.date.slice(0,10))} ${v.date.slice(11,16)}</b><p>Sąmata ${money(sum(v.budget))} · Prognozė ${money(sum(v.actual)+sum(v.remaining))} · Įsipareigota ${money(sum(v.committed||[0,0,0]))}</p></div>${btn('Peržiūrėti','version-detail',`data-id="${v.id}"`)}</div>`).join('')||'<p class="hint">Versijos dar neužfiksuotos.</p>'}</div>`}
function portfolioReserve(){const ps=db.projects,ms=ps.map(metrics),budget=sum(ms.map(m=>m.budget)),forecast=sum(ms.map(m=>m.forecast)),reserve=Math.max(0,budget-forecast),values=CAT.map((_,i)=>sum(ps.map(p=>actual(p.id)[i]+p.remaining[i]))),total=forecast+reserve;return `<div class="portfolio-reserve"><div class="section-title">Prognozės struktūra ir rezervas <span>Sąmata ${money(budget)}</span></div><div class="reserve-stack">${[...values,reserve].map((v,i)=>`<i class="segment-${i}" style="width:${total?v/total*100:0}%" title="${E([...CAT,'Rezervas'][i])}: ${money(v)}"></i>`).join('')}</div><div class="reserve-legend">${[...values,reserve].map((v,i)=>`<span><i class="segment-${i}"></i>${E([...CAT,'Rezervas'][i])}<b>${money(v)}</b></span>`).join('')}</div><p class="hint">Prognozuojamos kategorijų sąnaudos ir nepanaudotas sąmatos rezervas.${forecast>budget?' Prognozuojamas viršijimas '+money(forecast-budget)+'.':''}</p></div>`}
function committedForm(id){const p=P(id);modalContext={type:'committed',id};openDrawer('Projekto įsipareigojimai',p.name,`<div id="form-error"></div><form id="committed-form"><div class="form-grid">${CAT.map((c,i)=>`<label class="full">${E(c)} · įsipareigota, EUR *<input name="committed${i}" type="number" min="0" max="${p.remaining[i]}" step="0.01" required value="${committed(p)[i]}"><span class="hint">Likusių darbų įvertinimas ${money(p.remaining[i])}</span></label>`).join('')}<label class="full">Pakeitimo pagrindas *<textarea name="reason" required maxlength="500" rows="3" placeholder="Pvz., patvirtintas medžiagų užsakymas"></textarea></label></div></form><div class="note-box">${icon('file')}<div>Įsipareigojimai yra likusių darbų įvertinimo dalis. Jei naujas užsakymas viršija šį įvertinimą, pirmiausia patikslinkite likusių darbų sąnaudas.</div></div>`,formFooter('Išsaugoti įsipareigojimus','save-committed'))}

function resourcesPage(){let crewTab=state.resource==='crews';return header('Technika ir brigados','Resursų užimtumas pagal darbų plano rezervacijas.',iconBtn('calendar','Atidaryti planą','nav','data-page="schedule"'))+`<section class="card"><div class="card-head"><div class="segmented">${btn('Brigados','resource-tab','data-tab="crews"',crewTab?'active':'')}${btn('Technika','resource-tab','data-tab="machines"',!crewTab?'active':'')}</div><input type="date" id="resource-date" aria-label="Resursų užimtumo data" value="${state.resourceDate||today()}"></div><div class="panel"><div class="resource-grid">${(crewTab?crews:machines).filter(r=>searchMatch(r.name+' '+(r.model||r.lead))).map(r=>{let date=state.resourceDate||today(),ts=db.tasks.filter(t=>(crewTab?t.crew===r.id:t.machine===r.id)&&t.start<=date&&t.end>=date);return `<article class="resource"><div class="resource-header"><div class="project-icon">${icon(crewTab?'users':'truck')}</div><div><b>${E(r.name)}</b><small>${E(crewTab?r.lead:r.model)}</small></div></div><dl><dt>${crewTab?'Komandos dydis':'Inventorinis Nr.'}</dt><dd>${crewTab?r.size+' darbuotojai':E(r.id)}</dd><dt>Užimtumas ${short(date)}</dt><dd>${tag(ts.length>1?'Viršijimas':ts.length?'Vykdoma':'Laisva')}</dd>${!crewTab?`<dt>Vidinis valandinis įkainis</dt><dd>${money(r.rate)} / val.</dd>`:''}</dl>${ts.map(t=>`<div class="note-box"><div><b>${E(P(t.project).name)}</b><br>${E(t.name)}<br>${short(t.start)}–${short(t.end)} ${btn('Keisti →','edit-task',`data-id="${t.id}"`,'subtle')}</div></div>`).join('')}${!ts.length?'<p class="hint">Pasirinktai dienai rezervacijų nėra.</p>':''}</article>`}).join('')}</div></div></section>`}
function docTable(ds){return ds.length?`<div class="table-wrap"><table><thead><tr><th>Dokumentas</th><th>Objektas</th><th>Tipas</th><th>Versija / data</th><th>Būsena</th><th></th></tr></thead><tbody>${ds.map(d=>`<tr><td><div class="file-name"><span class="file-icon">${d.data?'FAILAS':'REG.'}</span><button class="rowlink" data-action="doc-detail" data-id="${d.id}">${E(d.name)}</button></div><small>${E(d.owner)}</small></td><td>${E(P(d.project).name)}</td><td>${E(d.kind)}</td><td>v${E(d.version)}<small>${full(d.date)}</small></td><td>${tag(d.status)}</td><td>${btn(icon('right'),'doc-detail',`data-id="${d.id}" aria-label="Atverti dokumentą ${E(d.name)}"`,'subtle')}</td></tr>`).join('')}</tbody></table></div>`:empty('Dokumentų pagal pasirinktus filtrus nėra.')}
function docsPage(){let ds=db.docs.filter(d=>(state.projectFilter==='all'||d.project===state.projectFilter)&&(state.status==='all'||d.status===state.status)&&searchMatch(d.name+' '+P(d.project).name+' '+d.kind));return header('Dokumentai','Sutartys, brėžiniai, protokolai ir atliktų darbų aktai.',iconBtn('upload','Įkelti dokumentą','new-doc','','primary'))+`<section class="card"><div class="filterbar">${projectFilter()}<select id="status-filter" aria-label="Dokumento būsena">${options(['Laukia tvirtinimo','Patvirtinta','Aktuali'],state.status,'Visos būsenos')}</select><span class="grow">${ds.length} dokumentai</span></div>${docTable(ds)}</section>`}
function reportsPage(){let ps=db.projects.filter(p=>(state.projectFilter==='all'||p.id===state.projectFilter)&&searchMatch(p.name+' '+p.client)),ms=ps.map(metrics),revenue=sum(ps.map(p=>p.revenue)),forecast=sum(ms.map(m=>m.forecast));return header('Projektų ataskaita','Sąmatos vykdymas, sąnaudos ir prognozuojamas rezultatas.',iconBtn('print','Spausdinti / PDF','print')+iconBtn('down','Eksportuoti CSV','export-report','','primary'))+`<section class="card"><div class="filterbar">${projectFilter()}${dateFilters()}<span class="grow">Ataskaitos data ${full(today())} · be PVM</span></div><div class="panel">${periodStats(state.projectFilter==='all'?null:state.projectFilter)}<div class="note-box">${icon('chart')}<div>Einamasis rezultatas skaičiuojamas pagal patvirtintus įrašus pasirinktame laikotarpyje. Žemiau pateikta viso projekto sąmata ir užbaigimo prognozė.</div></div><div class="subhead"><h3>Viso projekto planas ir prognozė</h3></div><div class="project-stats"><div><small>Sutarčių vertė</small><strong>${money(revenue)}</strong></div><div><small>Patvirtintas faktas</small><strong>${money(sum(ms.map(m=>m.cost)))}</strong></div><div><small>Prognozė užbaigus</small><strong>${money(forecast)}</strong></div><div><small>Prognozuojama marža</small><strong>${num(revenue?(revenue-forecast)/revenue*100:0,1)}%</strong></div></div><div class="section-title">Sąmatos panaudojimas <span>Patvirtintas faktas / sąmata</span></div>${ps.map(p=>{let m=metrics(p);return `<div class="report-row"><span>${E(p.name)}</span><div class="progress"><i style="width:${Math.min(100,m.budget?m.cost/m.budget*100:0)}%"></i></div><span style="text-align:right">${num(m.budget?m.cost/m.budget*100:0,1)}%</span></div>`}).join('')}</div><div class="table-wrap"><table><thead><tr><th>Objektas</th><th class="num">Sutarties vertė</th><th class="num">Sąmata</th><th class="num">Faktas</th><th class="num">Prognozė</th><th class="num">Rezultatas</th><th class="num">Marža</th></tr></thead><tbody>${ps.map(p=>{let m=metrics(p);return `<tr><td>${E(p.name)}</td><td class="num">${money(p.revenue)}</td><td class="num">${money(m.budget)}</td><td class="num">${money(m.cost)}</td><td class="num">${money(m.forecast)}</td><td class="num">${money(p.revenue-m.forecast)}</td><td class="num ${m.margin<0?'negative':''}">${num(m.margin,1)}%</td></tr>`}).join('')}<tr class="total"><td>Iš viso</td><td class="num">${money(revenue)}</td><td class="num">${money(sum(ms.map(m=>m.budget)))}</td><td class="num">${money(sum(ms.map(m=>m.cost)))}</td><td class="num">${money(forecast)}</td><td class="num">${money(revenue-forecast)}</td><td class="num">${num(revenue?(revenue-forecast)/revenue*100:0,1)}%</td></tr></tbody></table></div></section>`}
function settingsPage(){return header('Nustatymai','Darbo aplinka ir duomenų kopijos.')+`<section class="card"><div class="card-head"><h2>Darbo aplinka</h2></div><div class="settings-row"><div><h3>Aktyvus naudotojas</h3><p>Darius Kazlauskas · Projekto vadovas</p></div><span class="tag green">Aktyvus</span></div><div class="settings-row"><div><h3>Duomenų režimas</h3><p>Šis prototipas naudoja pavyzdinius duomenis. Pakeitimai saugomi šioje naršyklėje. Bendras kelių naudotojų darbas ir tikras prisijungimas šiame variante neįjungti.</p></div><span class="tag gray">Vietinė darbo aplinka</span></div><div class="settings-row"><div><h3>Duomenų kopija</h3><p>Atsisiųskite projektus, planą, žurnalą ir dokumentų registrą JSON formatu. Kopijoje bus ir įkelti failai.</p></div>${iconBtn('down','Atsisiųsti kopiją','backup')}</div><div class="settings-row"><div><h3>Pradiniai pavyzdiniai duomenys</h3><p>Atkurkite pradinę būseną po demonstracijos. Prieš atkūrimą automatiškai atsisiunčiama dabartinių duomenų kopija.</p></div>${btn('Atkurti duomenis','reset-dialog','','outline-warning')}</div></section>`}
function render(){const pending=db.logs.filter(l=>l.status==='Laukia tvirtinimo').length;const nav=[['overview','grid'],['projects','folder'],['schedule','calendar'],['journal','journal'],['income','euro'],['budget','cost'],['resources','truck'],['docs','file']];document.getElementById('app').innerHTML=`<main class="shell"><aside class="sidebar ${state.menu?'open':''}"><a class="brand" href="#top" data-action="nav" data-page="overview"><span class="brand-mark">${icon('road')}</span><span>kelio valdymas<small>DARBŲ KONTROLĖ</small></span></a><div class="nav-label">DARBO APLINKA</div><nav>${nav.map(([id,ic])=>`<a href="#${routes[id]}" data-action="nav" data-page="${id}" class="${state.page===id||(id==='projects'&&state.page==='project')?'active':''}" ${state.page===id?'aria-current="page"':''}>${icon(ic)}<span class="nav-text">${labels[id]}</span>${id==='journal'&&pending?`<b class="nav-count">${pending}</b>`:''}</a>`).join('')}</nav><div class="side-bottom"><nav>${[['reports','chart'],['settings','settings']].map(([id,ic])=>`<a href="#${routes[id]}" data-action="nav" data-page="${id}" class="${state.page===id?'active':''}">${icon(ic)}<span class="nav-text">${labels[id]}</span></a>`).join('')}</nav><div class="user"><span class="avatar">DK</span><div><b>Darius Kazlauskas</b><small>Projekto vadovas</small></div></div></div></aside><section class="workspace"><header class="topbar"><div class="top-left">${btn(icon('menu'),'mobile-menu','aria-label="Atverti meniu"','mobile')}<div class="crumb"><span>Darbo aplinka</span><span>/</span><strong>${labels[state.page]}</strong></div></div><div class="top-right"><label class="search">${icon('search')}<input id="global-search" placeholder="Ieškoti…" aria-label="Paieška" value="${E(state.query)}"></label><span class="date-top">${full(today())}</span><span class="demo">PAVYZDINIAI DUOMENYS</span></div></header><div class="content"><div class="print-head"><h2>Kelio darbų valdymas</h2><p>${full(today())}</p></div>${({overview,projects:projectsPage,project:selectedProject,schedule:schedulePage,journal:journalPage,income:incomePage,budget:budgetPage,resources:resourcesPage,docs:docsPage,reports:reportsPage,settings:settingsPage}[state.page]||overview)()}</div></section></main>`}
let modalContext=null,lastFocus=null;
function openDrawer(title,subtitle,body,footer='',eyebrow='PROJEKTO DUOMENYS'){lastFocus=document.activeElement;document.getElementById('overlay').innerHTML=`<div class="drawer-backdrop" data-close-bg="1"><section class="drawer" role="dialog" aria-modal="true" aria-label="${E(title)}"><div class="drawer-head"><div><div class="eyebrow">${E(eyebrow)}</div><h2>${E(title)}</h2><p>${E(subtitle)}</p></div>${btn('×','close-drawer','aria-label="Uždaryti"','close')}</div><div class="drawer-body">${body}</div>${footer?`<div class="drawer-footer">${footer}</div>`:''}</section></div>`;setTimeout(()=>{document.querySelector('#overlay input, #overlay select, #overlay button')?.focus()},0)}
function closeDrawer(){document.getElementById('overlay').innerHTML='';modalContext=null;lastFocus?.isConnected&&lastFocus.focus()}
function error(text){const box=document.querySelector('#form-error');if(box){box.innerHTML=`<div class="error" role="alert">${E(text)}</div>`;box.scrollIntoView({block:'nearest'})}}
const formFooter=(label,action,cls='primary')=>btn('Atšaukti','close-drawer')+btn(label,action,'',cls);
const formVal=name=>document.querySelector(`#overlay [name="${name}"]`)?.value?.trim()||'';
const formNum=name=>Number(formVal(name));
function projectForm(id){const p=id?P(id):null;modalContext={type:'project',id};openDrawer(p?'Projekto duomenys':'Naujas projektas',p?p.id:'Sutartis, atsakomybės ir patvirtinta sąmata',`<div id="form-error"></div><form id="project-form"><div class="form-grid"><label class="full">Projekto pavadinimas *<input name="name" required maxlength="100" value="${E(p?.name)}" placeholder="Objektas / ruožas"></label><label class="full">Užsakovas *<input name="client" required maxlength="100" value="${E(p?.client)}"></label><label>Sutarties Nr. *<input name="contract" required maxlength="40" value="${E(p?.contract)}"></label><label>Projekto vadovas *<select name="manager">${options(crews.map(c=>c.lead),p?.manager||crews[0].lead)}</select></label><label>Darbų pradžia *<input name="start" type="date" required value="${p?.start||today()}"></label><label>Darbų pabaiga *<input name="end" type="date" required value="${p?.end||plusDate(today(),21)}"></label><label>Sutarties vertė, EUR *<input name="revenue" required type="number" min="0" max="1000000000" step="0.01" value="${p?.revenue??''}"></label><label>Būsena<select name="state">${options(['Planuojamas','Vykdomas','Užbaigtas'],p?.state||'Planuojamas')}</select></label></div><div class="form-section">Patvirtinta projekto sąmata</div><div class="form-grid">${CAT.map((c,i)=>`<label class="${i===2?'full':''}">${E(c)}, EUR *<input name="budget${i}" type="number" required min="0" max="1000000000" step="0.01" value="${p?.budget[i]??''}" ${p?'readonly':''}></label>`).join('')}</div>${p?'<p class="hint">Patvirtinta sąmata fiksuota. Likusių darbų prognozė tikslinama sąmatos ekrane.</p>':''}</form>`,formFooter(p?'Išsaugoti pakeitimus':'Sukurti projektą','save-project'))}
function saveProject(){const f=document.getElementById('project-form');if(!f.reportValidity())return;let start=formVal('start'),end=formVal('end');if(start>end)return error('Darbų pabaiga negali būti ankstesnė už pradžią.');let old=modalContext.id?P(modalContext.id):null,ts=old?projectTasks(old.id):[];if(ts.some(t=>t.start<start||t.end>end))return error('Projekto laikotarpis turi apimti visus suplanuotus etapus. Pirmiausia patikslinkite jų datas.');if(formVal('state')==='Užbaigtas'&&old&&progress(old.id)<100)return error('Projekto užbaigimui turi būti patvirtinti visi suplanuoti darbų kiekiai.');const p={id:old?.id||'P-'+String(Math.max(26,...db.projects.map(p=>Number(p.id.split('-')[1])||0))+1).padStart(3,'0'),name:formVal('name'),client:formVal('client'),manager:formVal('manager'),contract:formVal('contract'),start,end,revenue:formNum('revenue'),state:formVal('state'),budget:old?.budget||CAT.map((_,i)=>formNum('budget'+i)),remaining:old?.remaining||CAT.map((_,i)=>formNum('budget'+i))};if(!old&&p.state==='Užbaigtas')return error('Naują projektą pirmiausia suplanuokite ir užregistruokite darbus.');if(sum(p.budget)<=0)return error('Patvirtinta sąmata turi būti didesnė už 0.');if(old)Object.assign(old,p);else db.projects.push(p);audit(p.id,old?'Atnaujinti projekto duomenys':'Sukurtas projektas',p.name);state.project=p.id;state.page='project';state.tab='summary';closeDrawer();mutation('Projekto duomenys išsaugoti');location.hash='project-control'}
function taskForm(id,project){let t=id?T(id):null,pid=t?.project||project||(state.projectFilter!=='all'?state.projectFilter:state.project);modalContext={type:'task',id};openDrawer(t?'Etapo planavimas':'Naujas etapas',t?P(t.project).name:'Terminai, kiekis ir resursų rezervavimas',`<div id="form-error"></div><form id="task-form"><div class="form-grid"><label class="full">Projektas *<select name="project" id="task-project" ${t?'disabled':''}>${options(db.projects.filter(p=>p.state!=='Užbaigtas'||p.id===t?.project),pid)}</select></label><label class="full">Etapo pavadinimas *<input name="name" required maxlength="80" value="${E(t?.name)}"></label><label>Pradžia *<input type="date" name="start" required value="${t?.start||P(pid)?.start||today()}"></label><label>Pabaiga *<input type="date" name="end" required value="${t?.end||P(pid)?.end||today()}"></label><label>Brigada *<select name="crew">${options(crews.map(c=>({id:c.id,name:c.name+' · '+c.lead})),t?.crew||'A')}</select></label><label>Technika<select name="machine"><option value="">Nepriskirta</option>${options(machines.map(m=>({id:m.id,name:m.id+' · '+m.name})),t?.machine)}</select></label><label>Planuotas kiekis *<input name="qty" type="number" required min="0.01" max="1000000000" step="0.01" value="${t?.qty??''}"></label><label>Matavimo vnt.<select name="unit">${options(['m²','m³','m','t','vnt.'],t?.unit||'m²')}</select></label><label class="full">Etapo svoris projekto eigoje *<input type="number" name="weight" min="1" max="1000" required value="${t?.weight||10}"></label></div><div class="note-box">${icon('calendar')}<div>Rezervuojant tikrinamos visos brigados ir technikos datos. Projekto eiga skaičiuojama pagal etapų svorius ir patvirtintus kiekius.</div></div></form>`,formFooter('Išsaugoti planą','save-task'))}
function saveTask(){if(!document.getElementById('task-form').reportValidity())return;const old=modalContext.id?T(modalContext.id):null,project=formVal('project'),p=P(project),start=formVal('start'),end=formVal('end'),crew=formVal('crew'),machine=formVal('machine'),qty=formNum('qty');if(!p)return error('Pasirinkite projektą.');if(start>end)return error('Etapo pabaiga negali būti ankstesnė už pradžią.');if(start<p.start||end>p.end)return error(`Etapo datos turi patekti į projekto laikotarpį ${full(p.start)}–${full(p.end)}.`);const conflict=db.tasks.find(t=>t.id!==old?.id&&t.start<=end&&t.end>=start&&(t.crew===crew||(machine&&t.machine===machine)));if(conflict)return error(`${conflict.crew===crew?'Brigada '+crew:'Technika '+machine} jau rezervuota: ${P(conflict.project).name}, ${conflict.name} (${full(conflict.start)}–${full(conflict.end)}). Pakeiskite datas arba resursą.`);if(old&&qty<taskQty(old.id))return error('Planuotas kiekis negali būti mažesnis už jau patvirtintą kiekį.');if(old&&old.unit!==formVal('unit')&&db.logs.some(l=>l.task===old.id))return error('Matavimo vieneto keisti negalima, nes etapui yra žurnalo įrašų.');let t={id:old?.id||'T-'+uid().slice(0,8),project,name:formVal('name'),start,end,crew,machine,qty,unit:formVal('unit'),weight:formNum('weight')};if(old)Object.assign(old,t);else db.tasks.push(t);audit(project,old?'Atnaujintas etapo planas':'Pridėtas etapas',`${t.name} · ${full(start)}–${full(end)} · Brigada ${crew}`);closeDrawer();mutation('Darbų planas išsaugotas')}
const defaultTask=pid=>projectTasks(pid).find(t=>taskQty(t.id)<t.qty&&t.start<=today()&&t.end>=today())||projectTasks(pid).find(t=>taskQty(t.id)<t.qty)||projectTasks(pid)[0];
function logForm(id,project){const l=id?db.logs.find(l=>l.id===id):null;if(l&&!['Juodraštis','Grąžinta tikslinti'].includes(l.status))return;const pid=l?.project||project||(state.projectFilter!=='all'?state.projectFilter:state.project);modalContext={type:'log',id};openDrawer(l?'Tikslinti dienos įrašą':'Naujas dienos įrašas','Duomenys iš objekto · kiekiai ir einamosios sąnaudos',`<div id="form-error"></div><form id="log-form"><div class="form-grid"><label class="full">Projektas *<select name="project" id="log-project" ${l?'disabled':''}>${options(db.projects.filter(p=>p.state!=='Užbaigtas'||p.id===l?.project),pid)}</select></label><label class="full">Darbų etapas *<select name="task" id="log-task">${options(projectTasks(pid),l?.task||defaultTask(pid)?.id)}</select></label><label>Data *<input name="date" type="date" required max="${today()}" value="${l?.date||today()}"></label><label>Atliktas kiekis, <span id="log-unit">${E(T(l?.task||defaultTask(pid)?.id)?.unit||'vnt.')}</span><input name="qty" type="number" min="0" max="1000000000" step="0.01" required value="${l?.qty??''}"></label></div><div class="form-section">DU sąnaudos</div><div class="form-grid"><label>Bendros darbuotojų valandos *<input name="hours" type="number" min="0" max="10000" step="0.1" required value="${l?.hours??''}" data-calc="labor"></label><label>Vidinis DU įkainis, EUR / val.<input name="laborRate" type="number" min="0" max="10000" step="0.01" value="${l?.hours?numPlain(l.costs[0]/l.hours):23}" data-calc="labor"></label><label class="full">DU sąnaudos, EUR *<input name="cost0" type="number" min="0" max="100000000" step="0.01" required value="${l?.costs[0]??'0'}" data-total="1"></label></div><div class="form-section">Medžiagos</div><div class="form-grid"><label class="full">Medžiaga<input name="materialName" maxlength="100" value="${E(l?.materialName||'CTB mišinys')}" placeholder="Pvz., CTB mišinys"></label><label>Sunaudotas kiekis, t<input name="material" type="number" min="0" max="10000000" step="0.01" value="${l?.material||0}" data-calc="material"></label><label>Kaina, EUR / t<input name="materialRate" type="number" min="0" max="100000" step="0.01" value="${l?.material?numPlain(l.costs[1]/l.material):72}" data-calc="material"></label><label class="full">Medžiagų sąnaudos, EUR *<input name="cost1" type="number" min="0" max="100000000" step="0.01" required value="${l?.costs[1]??0}" data-total="1"></label></div><div class="form-section">Technika ir motovalandos</div><div class="form-grid"><label class="full">Technika<select name="machine" id="log-machine"><option value="">Nepriskirta</option>${options(machines.map(m=>({id:m.id,name:m.id+' · '+m.name})),l?.machine||T(l?.task||defaultTask(pid)?.id)?.machine)}</select></label><label>Motovalandos<input name="machineHours" type="number" min="0" max="10000" step="0.1" value="${l?.machineHours??0}" data-calc="machine"></label><label>Įkainis, EUR / motovalandą<input name="machineRate" type="number" min="0" max="100000" step="0.01" value="${l?.machineHours?numPlain(l.costs[2]/l.machineHours):(machines.find(m=>m.id===T(l?.task||defaultTask(pid)?.id)?.machine)?.rate||0)}" data-calc="machine"></label><label class="full">Technikos ir kuro sąnaudos, EUR *<input name="cost2" type="number" min="0" max="100000000" step="0.01" required value="${l?.costs[2]??0}" data-total="1"></label><label class="full">Pastaba<textarea name="note" rows="3" maxlength="1000">${E(l?.note)}</textarea></label></div><div class="form-total"><span>Einamosios dienos sąnaudos</span><strong id="log-total">${money(l?sum(l.costs):0)}</strong></div><p class="hint">Įkainiai skirti vidinėms einamosioms sąnaudoms įvertinti. Galutinę kategorijos sumą galima patikslinti. Faktas atnaujinamas patvirtinus įrašą.</p></form>`,btn('Atšaukti','close-drawer')+btn('Išsaugoti juodraštį','save-log','data-submit="0"')+btn('Pateikti tvirtinti','save-log','data-submit="1"','primary'))}
const numPlain=n=>Math.round(n*100)/100;
function saveLog(submit){if(!document.getElementById('log-form').reportValidity())return;const old=modalContext.id?db.logs.find(l=>l.id===modalContext.id):null,pid=formVal('project'),task=formVal('task'),t=T(task),date=formVal('date'),qty=formNum('qty');if(!t||t.project!==pid)return error('Pirmiausia pridėkite darbų etapą projekto plane.');if(date<P(pid).start||date>P(pid).end)return error('Įrašo data turi patekti į projekto laikotarpį.');if(qty+taskQty(t.id)>t.qty)return error(`Likęs nepatvirtintas etapo kiekis: ${num(Math.max(0,t.qty-taskQty(t.id)),2)} ${t.unit}. Patikslinkite kiekį arba darbų planą.`);if((formNum('machineHours')||formNum('cost2'))&&!formVal('machine'))return error('Technikos sąnaudoms arba motovalandų apskaitai pasirinkite techniką.');if(formNum('material')&&!formVal('materialName'))return error('Įrašykite sunaudotos medžiagos pavadinimą.');const l={id:old?.id||'Ž-'+String(Math.max(45,...db.logs.map(l=>Number(l.id.slice(2))||0))+1).padStart(3,'0'),project:pid,task,date,qty,hours:formNum('hours'),machineHours:formNum('machineHours'),machine:formVal('machine'),material:formNum('material'),materialName:formVal('materialName'),costs:CAT.map((_,i)=>formNum('cost'+i)),note:formVal('note'),author:'Darius Kazlauskas',status:submit?'Laukia tvirtinimo':'Juodraštis'};if(old)Object.assign(old,l);else db.logs.push(l);audit(pid,`${l.id} ${submit?'pateiktas tvirtinti':'išsaugotas kaip juodraštis'}`,`${t.name} · ${num(qty)} ${t.unit} · ${money(sum(l.costs))}`);closeDrawer();mutation(submit?'Dienos įrašas pateiktas tvirtinti':'Juodraštis išsaugotas')}
function logDetail(id){const l=db.logs.find(l=>l.id===id),t=T(l.task);modalContext={type:'log-detail',id};let fields=[['Projektas',P(l.project).name],['Etapas',t?.name],['Data',full(l.date)],['Būsena',l.status],['Atliktas kiekis',num(l.qty,2)+' '+t?.unit],['Darbuotojų valandos',num(l.hours,1)+' val.'],['Technika',(l.machine||t?.machine||'—')],['Motovalandos',num(l.machineHours||0,1)+' motov.'],['Medžiaga',l.materialName||'Mišinys / pagrindo medžiagos'],['Sunaudota',num(l.material||0,2)+' t'],...CAT.map((c,i)=>[c==='Darbas'?'DU sąnaudos':c,money(l.costs[i])]),['Iš viso',money(sum(l.costs))]];openDrawer('Dienos įrašas '+l.id,P(l.project).name,`<div class="detail-grid">${fields.map(([k,v])=>`<div><small>${E(k)}</small><b>${E(v)}</b></div>`).join('')}</div><div class="detail-note">${E(l.note||'Pastabų nėra.')}</div>${l.rejectReason?`<div class="note-box amber">Grąžinimo priežastis: ${E(l.rejectReason)}</div>`:''}<div class="status-note">Įvedė ${E(l.author)}${l.approvedBy?` · Patvirtino ${E(l.approvedBy)}`:''}. ${l.status==='Patvirtinta'?'Įrašas įtrauktas į projekto kiekius ir faktines sąnaudas.':'Įrašas neįtrauktas į patvirtintą faktą.'}</div>`,l.status==='Laukia tvirtinimo'?btn('Grąžinti tikslinti','reject-log',`data-id="${l.id}"`)+btn('Patvirtinti faktą','approve-log',`data-id="${l.id}"`,'primary'):['Juodraštis','Grąžinta tikslinti'].includes(l.status)?btn('Uždaryti','close-drawer')+btn('Redaguoti','edit-log',`data-id="${l.id}"`,'primary'):btn('Uždaryti','close-drawer'))}
function approveLog(id){const l=db.logs.find(l=>l.id===id);if(l?.status!=='Laukia tvirtinimo')return;const t=T(l.task);if(taskQty(t.id)+l.qty>t.qty){openDrawer('Kiekis viršija planą',l.id,`<div class="error">Patvirtinus įrašą, etapo kiekis viršytų planą. Pirmiausia patikslinkite planą arba grąžinkite įrašą tikslinti.</div>`,btn('Grąžinti tikslinti','reject-log',`data-id="${l.id}"`)+btn('Uždaryti','close-drawer'));return}l.status='Patvirtinta';l.approvedBy='Darius Kazlauskas';P(l.project).committed=committed(P(l.project)).map((c,i)=>Math.max(0,numPlain(c-l.costs[i])));P(l.project).remaining=P(l.project).remaining.map((r,i)=>Math.max(0,numPlain(r-l.costs[i])));audit(l.project,`Patvirtintas dienos įrašas ${id}`,`${num(l.qty)} ${t.unit} · ${money(sum(l.costs))} · atnaujinta projekto eiga ir sąnaudos`);closeDrawer();mutation('Faktas patvirtintas. Projekto kiekiai ir sąnaudos atnaujinti.')}
function rejectForm(id,income=false){modalContext={type:income?'reject-income':'reject',id};openDrawer('Grąžinti tikslinti',id,`<div id="form-error"></div><div class="form-grid"><label class="full">Tikslinimo priežastis *<textarea name="reason" maxlength="500" rows="4" required placeholder="Ką reikia patikslinti?"></textarea></label></div>`,formFooter('Grąžinti tikslinti',income?'save-reject-income':'save-reject'))}
function remainingForm(id){const p=P(id);modalContext={type:'remaining',id};openDrawer('Likusių darbų sąnaudos',p.name,`<div id="form-error"></div><form id="remaining-form"><div class="form-grid">${CAT.map((c,i)=>`<label class="full">${c}, EUR *<input name="remain${i}" type="number" min="0" max="1000000000" step="0.01" required value="${p.remaining[i]}"><span class="hint">Iš jų įsipareigota ${money(committed(p)[i])}</span></label>`).join('')}<label class="full">Pakeitimo priežastis *<textarea name="reason" required rows="3" maxlength="500" placeholder="Pvz., patikslintas medžiagų poreikis"></textarea></label></div></form><div class="note-box">${icon('chart')}<div>Patvirtinta sąmata nesikeičia. Šis įvertinimas kartu su faktu sudaro projekto užbaigimo prognozę.</div></div>`,formFooter('Atnaujinti prognozę','save-remaining'))}
function docForm(pid){modalContext={type:'doc'};const project=pid||(state.projectFilter!=='all'?state.projectFilter:state.project);openDrawer('Įkelti dokumentą','Failas ir jo duomenys projekto registre',`<div id="form-error"></div><form id="doc-form"><div class="form-grid"><label class="full">Projektas *<select name="project">${options(db.projects,project)}</select></label><label class="full">Dokumento pavadinimas *<input name="name" required maxlength="100"></label><label>Tipas<select name="kind">${options(['Sutartis','Brėžinys','Protokolas','Aktas','Medžiagų deklaracija','Kita'],'Protokolas')}</select></label><label>Versija *<input name="version" required value="1" maxlength="20"></label><label class="full">Failas *<input type="file" name="file" required accept=".pdf,.png,.jpg,.jpeg,.txt,.csv"><span class="hint">PDF, PNG, JPG, TXT arba CSV · iki 2 MB.</span></label><label>Būsena<select name="status">${options(['Laukia tvirtinimo','Aktuali'],'Laukia tvirtinimo')}</select></label><label>Registravimo data<input type="date" name="date" required value="${today()}"></label></div></form>`,formFooter('Išsaugoti dokumentą','save-doc'))}
async function saveDoc(){if(!document.getElementById('doc-form').reportValidity())return;const file=document.querySelector('#overlay [name=file]').files[0];if(!file)return error('Pasirinkite failą.');if(file.size>2*1024*1024)return error('Failas viršija 2 MB ribą.');if(!/\.(pdf|png|jpe?g|txt|csv)$/i.test(file.name))return error('Pasirinkite PDF, PNG, JPG, TXT arba CSV failą.');const payload={id:'D-'+uid().slice(0,8),project:formVal('project'),name:formVal('name'),kind:formVal('kind'),version:formVal('version'),date:formVal('date'),status:formVal('status'),owner:'Darius Kazlauskas',filename:file.name,size:file.size};if(db.docs.some(d=>d.project===payload.project&&d.name.toLowerCase()===payload.name.toLowerCase()&&d.version===payload.version))return error('Toks dokumentas su ta pačia versija jau yra registre. Įrašykite naują versijos numerį.');try{payload.data=await new Promise((resolve,reject)=>{let reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)});let candidate=JSON.stringify({...db,docs:[...db.docs,payload]});localStorage.setItem(KEY,candidate);db.docs.push(payload);audit(payload.project,'Įkeltas dokumentas',payload.name+' · v'+payload.version);closeDrawer();mutation('Dokumentas išsaugotas')}catch{error('Nepakanka vietos naršyklėje arba nepavyko perskaityti failo. Pasirinkite mažesnį failą.')}}
function docDetail(id){const d=db.docs.find(d=>d.id===id);modalContext={type:'doc-detail',id};openDrawer(d.name,P(d.project).name,`<div class="detail-grid">${[['Tipas',d.kind],['Versija','v'+d.version],['Data',full(d.date)],['Būsena',d.status],['Atsakingas',d.owner],['Failas',d.filename||'Registro kortelė']].map(([k,v])=>`<div><small>${E(k)}</small><b>${E(v)}</b></div>`).join('')}</div>${d.data&&/^data:image\/(png|jpeg)/.test(d.data)?`<div class="attach-preview"><img src="${d.data}" alt="${E(d.name)}"></div>`:''}${d.text?`<div class="detail-note" style="white-space:pre-wrap">${E(d.text)}</div><p class="hint">Pavyzdiniame registre pateikta dokumento kortelė. Originalą galite įkelti per dokumentų registrą.</p>`:`<div class="note-box">${icon('file')}<div>${E(d.filename)} · ${num(d.size/1024)} KB<br>Failą galite atsisiųsti ir peržiūrėti.</div></div>`}`,btn(d.data?'Atsisiųsti failą':'Atsisiųsti kortelę','download-doc',`data-id="${id}"`)+(d.status==='Laukia tvirtinimo'?btn('Patvirtinti dokumentą','approve-doc',`data-id="${id}"`,'primary'):btn('Uždaryti','close-drawer')))}
function costDetail(pid,cat){const ls=approved(pid).filter(l=>l.costs[cat]>0);openDrawer(CAT[cat]==='Darbas'?'DU sąnaudų detalizacija':CAT[cat]+' · detalizacija',P(pid).name,`<div class="table-wrap"><table><thead><tr><th>Data / šaltinis</th><th>Etapas</th><th class="num">Suma</th></tr></thead><tbody>${ls.map(l=>`<tr><td>${full(l.date)}<small>${l.id}</small></td><td>${E(T(l.task)?.name)}<small>${cat===0?num(l.hours)+' darbuotojų val.':cat===1?num(l.material||0)+' t':num(l.machineHours||0)+' motov.'}</small></td><td class="num">${money(l.costs[cat])}</td></tr>`).join('')}<tr class="total"><td colspan="2">Iš viso patvirtinta</td><td class="num">${money(sum(ls.map(l=>l.costs[cat])))}</td></tr></tbody></table></div>`,btn('Uždaryti','close-drawer'))}
function versionDetail(id){const v=db.versions.find(v=>v.id===id),cs=v.committed||[0,0,0],forecast=sum(v.actual)+sum(v.remaining),reserve=sum(v.budget)-forecast;openDrawer('Sąmatos versija V'+v.number,P(v.project).name+' · '+full(v.date.slice(0,10)),`<div class="table-wrap"><table><thead><tr><th>Kategorija</th><th class="num">Sąmata</th><th class="num">Faktas</th><th class="num">Įsipareigota</th><th class="num">Kiti likę darbai</th><th class="num">Prognozė</th></tr></thead><tbody>${CAT.map((c,i)=>`<tr><td>${E(c)}</td><td class="num">${money(v.budget[i])}</td><td class="num">${money(v.actual[i])}</td><td class="num">${money(cs[i])}</td><td class="num">${money(v.remaining[i]-cs[i])}</td><td class="num">${money(v.actual[i]+v.remaining[i])}</td></tr>`).join('')}</tbody></table></div><div class="reserve-strip"><div><b>Rezervas</b><p>Užfiksuotos versijos sąmata minus prognozė.</p></div><strong>${money(Math.max(0,reserve))}</strong></div><p class="hint">Užfiksuota būklė. Dabartiniai projekto duomenys gali būti pasikeitę.${!v.committed?' Šioje ankstesnėje versijoje įsipareigojimai nebuvo fiksuojami.':''}</p>`,btn('Uždaryti','close-drawer'))}

function download(name,content,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function csv(name,headers,rows){const safe=x=>{let s=String(x??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'};download(name,'\ufeff'+[headers,...rows].map(row=>row.map(safe).join(';')).join('\r\n'),'text/csv;charset=utf-8')}
function exportProjects(report=false){let ps=db.projects.filter(p=>(state.page!=='reports'||state.projectFilter==='all'||p.id===state.projectFilter)&&searchMatch(p.name+' '+p.client+' '+p.id+' '+p.manager)&&(state.page!=='projects'||state.status==='all'||p.state===state.status));csv(report?'Projektu_ataskaita.csv':'Projektai.csv',['Kodas','Objektas','Užsakovas','Vadovas','Sutarties vertė','Sąmata','Patvirtintas faktas','Prognozė','Prognozės rezervas','Darbų eiga %','Būsena'],ps.map(p=>{let m=metrics(p);return [p.id,p.name,p.client,p.manager,p.revenue,m.budget,m.cost,m.forecast,m.variance,m.progress,p.state]}));notify('CSV failas paruoštas')}
